from itertools import product, combinations

def reduce_instance(m, clauses):
    c=len(clauses)
    B=2
    total=m+c+1
    def encode(d):
        val=0; mult=1
        for x in d:
            val+=x*mult; mult*=B
        return val
    numbers=[]
    for var in range(1,m+1):
        pos=[0]*total
        neg=[0]*total
        pos[var-1]=1
        neg[var-1]=1
        for idx,cl in enumerate(clauses):
            p=m+idx
            if +var in cl:
                pos[p]=1
            if -var in cl:
                neg[p]=1
        numbers.append(encode(pos))
        numbers.append(encode(neg))
    for idx in range(c):
        d=[0]*total
        d[m+idx]=1
        numbers.append(encode(d))
    target_digits=[1]*m+[1]*c+[c]
    target=encode(target_digits)
    return numbers,target

def sat_bruteforce(m,clauses):
    for mask in range(1<<m):
        ok=True
        for cl in clauses:
            clause_ok=False
            for lit in cl:
                var=abs(lit)-1
                val=(mask>>var)&1
                if (lit>0 and val==1) or (lit<0 and val==0):
                    clause_ok=True;break
            if not clause_ok:
                ok=False;break
        if ok:
            return True
    return False

def subset_sum_possible(numbers,target):
    n=len(numbers)
    for r in range(n+1):
        for combo in combinations(range(n),r):
            if sum(numbers[i] for i in combo)==target:
                return True
    return False

# test all small instances
for m in range(0,4):
    # generate all possible clauses sets with 3 literals each distinct vars
    vars=list(range(1,m+1))
    # generate all possible clauses (choose 3 distinct vars, assign signs)
    clauses_list=[]
    if m>=3:
        from itertools import combinations, product
        for vars3 in combinations(vars,3):
            for signs in product([1,-1], repeat=3):
                clause=[signs[i]*vars3[i] for i in range(3)]
                clauses_list.append(clause)
    else:
        clauses_list=[[]]
    # test subsets of clauses up to 3
    for num_cl in range(0,4):
        from itertools import combinations
        for subset in combinations(clauses_list, num_cl):
            clauses=list(subset)
            nums,target=reduce_instance(m,clauses)
            sat=sat_bruteforce(m,clauses)
            ss=subset_sum_possible(nums,target)
            if sat!=ss:
                print('m',m,'clauses',clauses,'sat',sat,'ss',ss)
                raise SystemExit
print('all good')
